            public bool IsTuThoiHan { get; set; }
        }

        private static List<HinhPhatSegment> ParseHinhPhat(string input)
		{
			var results = new List<HinhPhatSegment>();
			if (string.IsNullOrWhiteSpace(input)) return results;

			var parts = input.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries)
						 	.Select(p => p.Trim())
						 	.Where(p => !string.IsNullOrWhiteSpace(p));

			foreach (var part in parts)
			{
				var segment = new HinhPhatSegment
				{
					Raw = part,
					IsThuThach = ContainsWord(part, "thử thách"),
                    IsAnTreo = ContainsWord(part, "án treo"),
                    IsPhatTien = ContainsWord(part, "phạt tiền")
                };

				segment.Nam = MatchIntBeforeUnit(part, "năm");
				segment.Thang = MatchIntBeforeUnit(part, "tháng");
				segment.Ngay = MatchIntBeforeUnit(part, "ngày");
                segment.SoTien = MatchIntBeforeUnit(part, "VND");
                segment.OtherText = BuildOtherText(part);

				results.Add(segment);
			}

			return results;
		}

		private static bool ContainsWord(string text, string phrase)
		{
			if (string.IsNullOrEmpty(text)) return false;
			return text.IndexOf(phrase, StringComparison.OrdinalIgnoreCase) >= 0;
		}

		private static int? MatchIntBeforeUnit(string text, string unit)
		{
			var pattern = $@"(\d+)\s*{Regex.Escape(unit)}\b";
			var m = Regex.Match(text, pattern, RegexOptions.IgnoreCase);
			if (!m.Success) return null;
			int value;
			if (int.TryParse(m.Groups[1].Value, out value)) return value;
			return null;
		}

		private static string BuildOtherText(string part)
		{
			var cleaned = part;
			cleaned = Regex.Replace(cleaned, @"\b\d+\s*năm\b", string.Empty, RegexOptions.IgnoreCase);
			cleaned = Regex.Replace(cleaned, @"\b\d+\s*tháng\b", string.Empty, RegexOptions.IgnoreCase);
			cleaned = Regex.Replace(cleaned, @"\b\d+\s*ngày\b", string.Empty, RegexOptions.IgnoreCase);
			cleaned = Regex.Replace(cleaned, @"\bán\s*treo\b", string.Empty, RegexOptions.IgnoreCase);
			cleaned = Regex.Replace(cleaned, @"\bthử\s*thách\b", string.Empty, RegexOptions.IgnoreCase);
			cleaned = Regex.Replace(cleaned, @"\s{2,}", " ").Trim(new[] { ' ', ',', ';', '-' }).Trim();
			return cleaned;
		}
