                        if (thaBiAn.HOTENBO != null && thaBiAn.HOTENBO != "")
                        {
                            r.BICAO_TENBO = "\r\n    Con ông: " + thaBiAn.HOTENBO + ";";
                        }
                        // ten bo bi cao
                        if (thaBiAn.HOTENME != null && thaBiAn.HOTENME != "")
                        {
                            r.BICAO_TENME = " Con bà: " + thaBiAn.HOTENME;
                        }
                        // nguoi ky chanh an
                        decimal chanhAnId = Convert.ToDecimal(thaBanAnQuyetDinh.NGUOIKY);
                        DM_CANBO cb = dt.DM_CANBO.Where(x => x.ID == chanhAnId).FirstOrDefault();
                        r.CANBOTEN = cb.HOTEN;
                        // TEN VKS
                        r.TENVKSVIETTAT = strTenVks;
                        // tinh, tp toa KV
                        r.NOICHAPHANH = diaPhuongToaKV;
                        objhs.DTBM03THA.AddDTBM03THARow(r);
                        objhs.AcceptChanges();
                        rpt03THA rpt = new rpt03THA();
                        rpt.DataSource = objhs;
                        rptView.OpenReport(rpt);
                    } else
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                }
            }
            catch (Exception ex) { ltlmsg.InnerText = ex.Message; }
        }

