        private void getHinhPhatTHA_tonghop_ST(Dictionary<decimal, Dictionary<decimal, HinhPhatByToiDanhID>> toiDanhmap, THA_SOTHAM_BANAN_DIEU_CHITIET thaChiTiet)
        {
            decimal? donViId = thaChiTiet.TOIDANHID;

            String[] arrToiDanh = null;
            DM_BOLUAT_TOIDANH objTD = dt.DM_BOLUAT_TOIDANH.Where(x => x.ID == donViId).Single();
            arrToiDanh = objTD.ARRSAPXEP.Split('/');
            decimal ChuongID = Convert.ToDecimal(arrToiDanh[0] + "");
            decimal DieuId = Convert.ToDecimal(arrToiDanh[1] + "");
            decimal hinhPhatID = (decimal)thaChiTiet.HINHPHATID;

            if (toiDanhmap.ContainsKey(DieuId))
            {
                if (toiDanhmap[DieuId].ContainsKey(hinhPhatID))
                {
                    toiDanhmap[DieuId][hinhPhatID].SoTien += thaChiTiet.SH_VALUE;
                    toiDanhmap[DieuId][hinhPhatID].Ngay += thaChiTiet.TG_NGAY;
                    toiDanhmap[DieuId][hinhPhatID].Thang += thaChiTiet.TG_THANG;
                    toiDanhmap[DieuId][hinhPhatID].Nam += thaChiTiet.TG_NAM;
                }
                else
                {
                    toiDanhmap[DieuId].Add(hinhPhatID, new HinhPhatByToiDanhID
                    {
                        SoTien = thaChiTiet.SH_VALUE,
                        Ngay = thaChiTiet.TG_NGAY,
                        Thang = thaChiTiet.TG_THANG,
                        Nam = thaChiTiet.TG_NAM,
                    });
                }

            }
            else
            {

                Dictionary<decimal, HinhPhatByToiDanhID> hinhPhatGroup = new Dictionary<decimal, HinhPhatByToiDanhID>();
                hinhPhatGroup.Add(hinhPhatID, new HinhPhatByToiDanhID
                {
                    SoTien = thaChiTiet.SH_VALUE,
                    Ngay = thaChiTiet.TG_NGAY,
                    Thang = thaChiTiet.TG_THANG,
                    Nam = thaChiTiet.TG_NAM,

                });
                toiDanhmap.Add(DieuId, hinhPhatGroup);
            }
        }

