        public string docSo(long number)
        {
            string[] ChuSo = { "không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín" };
            string[] Hang = { "", "nghìn", "triệu", "tỷ" };

            if (number == 0) return "không";

            string ketQua = "";
            int i = 0; // chỉ số đơn vị: nghìn, triệu, tỷ

            while (number > 0)
            {
                int threeDigits = (int)(number % 1000);
                if (threeDigits != 0)
                {
                    string str = DocBaChuSo(threeDigits, ChuSo);
                    if (i > 0)
                        ketQua = str + " " + Hang[i] + " " + ketQua;
                    else
                        ketQua = str + " " + ketQua;
                }
                number /= 1000;
                i++;
            }

            return ketQua.Trim();
        }

        private string DocBaChuSo(int number, string[] ChuSo)
        {
            int tram = number / 100;
            int chuc = (number % 100) / 10;
            int donvi = number % 10;

            string result = "";

            if (tram > 0)
            {
                result += ChuSo[tram] + " trăm";
                if (chuc == 0 && donvi > 0) result += " lẻ";
            }

            if (chuc > 1)
            {
                result += " " + ChuSo[chuc] + " mươi";
                if (donvi == 1) result += " mốt";
                else if (donvi == 5) result += " lăm";
                else if (donvi > 0) result += " " + ChuSo[donvi];
            }
            else if (chuc == 1)
            {
                result += " mười";
                if (donvi == 5) result += " lăm";
                else if (donvi > 0) result += " " + ChuSo[donvi];
            }
            else if (chuc == 0 && donvi > 0 && tram == 0)
            {
                result += ChuSo[donvi];
            }
            else if (chuc == 0 && donvi > 0)
            {
                result += " " + ChuSo[donvi];
            }

            return result.Trim();
        }

        private string getTenToaHeader(DM_TOAAN oT)
        {
            try
            {
                string strTenToa = "Tòa án nhân dân tối cao";
                strTenToa = oT.MA_TEN;
                if (strTenToa.Contains("cấp cao"))
                {
                    strTenToa = strTenToa.Replace("cấp cao", "cấp cao\n");
                }
                else if (!strTenToa.Contains("tối cao"))
                {
                    if (strTenToa.ToLower().Contains("khu vực"))
                    {
                        strTenToa = strTenToa.Split(',')[0];
                    }
                    strTenToa = strTenToa.Replace("Tòa án nhân dân", "Tòa án nhân dân\n").Replace(", tỉnh", " - ");
                }
                return strTenToa.ToUpper();
            }
            catch { return ""; }
        }

