        public static string CleanCaseName(string input)
        {
            if (string.IsNullOrWhiteSpace(input)) return input;

            return Regex.Replace(
                input,
                @"^\s*([-]|\d+(\.\d+)*\.?)(\s+)",
                ""
            ).Trim();
        }
        private string getTenToaV2(decimal TOAANID)
        {
            try
            {
                string strTenToa = "Tòa án nhân dân tối cao";
                DM_TOAAN oT = dt.DM_TOAAN.Where(x => x.ID == TOAANID).FirstOrDefault();
                strTenToa = oT.MA_TEN;
                if (strTenToa.Contains("cấp cao"))
                {
                    strTenToa = strTenToa.Replace("cấp cao", "cấp cao");
                }
                else if (!strTenToa.Contains("tối cao"))
                {
                    strTenToa = strTenToa.Replace(",", " - "); ;
                }
                return strTenToa;
            }
            catch { return ""; }
        }
