        private string getCanBoGioiTinh(decimal TPID)
        {
            try
            {
                string strTenToa = "";
                DM_CANBO oCanbo = dt.DM_CANBO.Where(x => x.ID == TPID).FirstOrDefault();
                if (oCanbo != null)
                {
                    if (oCanbo.GIOITINH == 1)
                        strTenToa = "Ông " + oCanbo.HOTEN;
                    else
                        strTenToa = "Bà " + oCanbo.HOTEN;
                }
                return strTenToa;
            }
            catch { return ""; }
        }
