                        r.DIADIEM = strDiadiem;
                        r.SOTHULY = oSTTL.SOTHULY;
                        DateTime oNgayTL = (DateTime)oSTTL.NGAYTHULY;
                        r.NGAYTHULY = oNgayTL.Day.ToString();
                        r.THANGTHULY = oNgayTL.Month.ToString();
                        r.NAMTHULY = oNgayTL.Year.ToString();
                        r.TENTOAAN = getTenToa((decimal)oSTTL.TOAANID);
                        r.NGUOIKHOIKIEN = strND_Gioitinh + " " + strND_Hoten;
                        r.DIACHI = strND_Diachi;

                        r.SOQD = oQD.SOQD;
                        DateTime oNgayQD = (DateTime)oQD.NGAYQD;
                        r.NGAYQD = oNgayQD.Day.ToString();
                        r.THANGQD = oNgayQD.Month.ToString();
                        r.NAMQD = oNgayQD.Year.ToString();
                        //Hội đồng xét xử
                        List<ADS_SOTHAM_HDXX> lstHD = dt.ADS_SOTHAM_HDXX.Where(x => x.DONID == vDonID && x.MAVAITRO == ENUM_NGUOITIENHANHTOTUNG.THAMPHAN).ToList();
                        //Thẩm phán chủ tọa
                        if (lstHD.Count > 0)
                        {
                            decimal IDCB = (decimal)lstHD[0].CANBOID;
                            DM_CANBO oCanbo = dt.DM_CANBO.Where(x => x.ID == IDCB).FirstOrDefault();
                            if (oCanbo.GIOITINH == 1)
                                r.THAMPHANCHUTOA = "Ông " + oCanbo.HOTEN;
                            else
                                r.THAMPHANCHUTOA = "Bà " + oCanbo.HOTEN;
                        }
                        objds.DTBM47DS.AddDTBM47DSRow(r);
                        objds.AcceptChanges();
                        //Nguyên đơn
                        objds = FillDSNguyenDon_ADS(oDon, objds, lstND);
                        //Bị đơn
                        objds = FillDSBiDon_ADS(oDon, objds, lstBD);
                        //NVLQ
                        objds = FillDSNguoiNVLQ_ADS(oDon, objds, lstNVLQ);

                        rpt79DS rpt = new rpt79DS();
                        rpt.DataSource = objds;
                        rptView.OpenReport(rpt);
                    }
                    else
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                }
            }
            catch (Exception ex) { ltlmsg.InnerText = ex.Message; }
        }
        private void LoadReportAHN_ST(decimal vDonID, AHN_DON oDon)
        {
            try
            {
                rptView.Visible = true;
                string strDiadiem = getDiaDiem((decimal)oDon.TOAANID);
                string strTenToaAn= getTenToa((decimal)oDon.TOAANID);
                decimal DonViID = Convert.ToDecimal(Session[ENUM_SESSION.SESSION_DONVIID]);
                string vMaBC = "";
                if (Request["BM"] != null)
                    vMaBC = Request["BM"] + "";
                List<AHN_SOTHAM_THULY> lstThuLy = dt.AHN_SOTHAM_THULY.Where(x => x.DONID == vDonID).OrderByDescending(x => x.NGAYTHULY).ToList();
                List<AHN_DON_THAMPHAN> lstGQD = dt.AHN_DON_THAMPHAN.Where(x => x.DONID == vDonID && x.MAVAITRO == ENUM_VAITROTHAMPHAN.VTTP_GIAIQUYETDON).OrderByDescending(x => x.NGAYPHANCONG).ToList();

                List<AHN_DON_DUONGSU> lstND = dt.AHN_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.NGUYENDON).OrderByDescending(x => x.ISDAIDIEN).ToList();
                List<AHN_DON_DUONGSU> lstBD = dt.AHN_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.BIDON).ToList();
                List<AHN_DON_DUONGSU> lstNVLQ = dt.AHN_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.QUYENNVLQ).ToList();

                List<AHN_DON_DUONGSU> lstNDDD = dt.AHN_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.NGUYENDON && x.ISDAIDIEN == 1).ToList();
                //Nguyên đơn đại diện
                string strND_Hoten = "", strND_Diachi = "", strND_Gioitinh = "", strND_Dienthoai = "", strND_Fax = "",
                    strND_Email = "", strND_NoiLamViec = "", strLoaihinhdon = "";
                if (oDon.HINHTHUCNHANDON == 1)
                    strLoaihinhdon = "nộp trực tiếp";
                else if (oDon.HINHTHUCNHANDON == 2)
                    strLoaihinhdon = "do tổ chức dịch vụ bưu chính chuyển đến ";
                if (oDon.HINHTHUCNHANDON == 3)
                    strLoaihinhdon = "nộp trực tuyến";
                string strTenQHPL = "";
                //DM_DATAITEM oTQHPL = dt.DM_DATAITEM.Where(x => x.ID == oDon.QUANHEPHAPLUATID).FirstOrDefault();
                //strTenQHPL = oTQHPL.TEN;
                strTenQHPL = getQuanhephapluat_name("AHN", "DON", "", Convert.ToDecimal(oDon.ID));

                if (lstNDDD.Count > 0)
                {
                    AHN_DON_DUONGSU oNDDD = lstNDDD[0];

                    strND_Hoten = oNDDD.LOAIDUONGSU == 1 ? Cls_Comon.FormatTenRieng(oNDDD.TENDUONGSU) : Cls_Comon.FormatTenTochuc(oNDDD.TENDUONGSU);

                    if (oNDDD.LOAIDUONGSU == 1)
                    {
                        if (oNDDD.GIOITINH == 1)
                            strND_Gioitinh = "Ông";
                        else strND_Gioitinh = "Bà";
                        if (oNDDD.TAMTRUID != null) strND_Diachi = getDiachi((decimal)oNDDD.TAMTRUID);
                        strND_Diachi = oNDDD.TAMTRUCHITIET + " " + strND_Diachi;

                    }
                    else
                    {
                        if (oNDDD.NDD_DIACHIID != null) strND_Diachi = getDiachi((decimal)oNDDD.NDD_DIACHIID);
                        strND_Diachi = oNDDD.NDD_DIACHICHITIET + " " + strND_Diachi;
                    }
                    strND_Dienthoai = oNDDD.DIENTHOAI;
                    strND_Fax = oNDDD.FAX;
                    strND_Email = oNDDD.EMAIL;
                    strND_NoiLamViec = oNDDD.DIACHICOQUAN;
                }
                if (vMaBC == "01-DS")
                {
                    idTitle.Text = "01-DS. Biên bản giao nhận tài liệu, chứng cứ";
                    DTBIEUMAU objds = new DTBIEUMAU();

                    List<AHN_DON_TAILIEU> lstTL = dt.AHN_DON_TAILIEU.Where(x => x.DONID == vDonID).ToList();
                    if (lstTL.Count == 0)
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                    foreach (AHN_DON_TAILIEU t in lstTL.GroupBy(x => new { x.NGUOIBANGIAO, x.NGAYBANGIAO, x.NGUOINHANID }).Select(x => x.FirstOrDefault()))
                    {
                        if (t.NGAYBANGIAO != null && t.NGUOIBANGIAO != null && t.NGUOINHANID != null)
                        {
                            DTBIEUMAU.DTBANGIAOTLCCRow r = objds.DTBANGIAOTLCC.NewDTBANGIAOTLCCRow();
                            r.ID = Guid.NewGuid().ToString();
                            r.QUANHEPHAPLUAT = strTenQHPL;
                            DateTime dN = (DateTime)t.NGAYBANGIAO;
                            r.NGAYBANGIAO = dN.ToString("dd/MM/yyyy");
                            r.NGAY = dN.Day.ToString();
                            r.THANG = dN.Month.ToString();
                            r.NAM = dN.Year.ToString();
                            r.NGUOINHAN = getCanBo((decimal)t.NGUOINHANID);
                            if (t.LOAIDOITUONG == 1)
                            {
                                r.TUCACHTOTUNG = "Người tham gia tố tụng";
                                AHN_DON_THAMGIATOTUNG oTT = dt.AHN_DON_THAMGIATOTUNG.Where(x => x.ID == t.NGUOIBANGIAO).FirstOrDefault();
                                r.NGUOIBANGIAO = oTT.HOTEN;
                            }
                            else
                            {
                                r.TUCACHTOTUNG = "Đương sự";
                                AHN_DON_DUONGSU oDS = dt.AHN_DON_DUONGSU.Where(x => x.ID == t.NGUOIBANGIAO).FirstOrDefault();
                                r.NGUOIBANGIAO = oDS.TENDUONGSU;
                            }
                            objds.DTBANGIAOTLCC.AddDTBANGIAOTLCCRow(r);
                            foreach (AHN_DON_TAILIEU tl in lstTL.Where(x => x.NGUOIBANGIAO == t.NGUOIBANGIAO && x.NGAYBANGIAO == t.NGAYBANGIAO && x.NGUOINHANID == t.NGUOINHANID).ToList())
                            {
                                DTBIEUMAU.DTBANGIAODSRow rt = objds.DTBANGIAODS.NewDTBANGIAODSRow();
                                rt.ID = Guid.NewGuid().ToString();
                                rt.BGID = r.ID;
                                rt.TENTAILIEU = tl.TENTAILIEU;
                                objds.DTBANGIAODS.AddDTBANGIAODSRow(rt);
                            }
                        }
                    }
                    objds.AcceptChanges();
                    rpt01DS rpt = new rpt01DS();
                    rpt.DataSource = objds;
                    rptView.OpenReport(rpt);

                }
                else if (vMaBC == "05-VDS")
                {
                    idTitle.Text = "05-VDS. Thông báo nộp tiền tạm ứng lệ phí yêu cầu giải quyết việc dân sự";
                    List<AHN_DON_XULY> lstTL = dt.AHN_DON_XULY.Where(x => x.DONID == vDonID && x.LOAIGIAIQUYET == 5).OrderByDescending(x => x.NGAYGQ_YC).ToList();
                    List<AHN_ANPHI> lstAP = dt.AHN_ANPHI.Where(x => x.DONID == vDonID && x.TINHTRANG == 0).ToList();
                    List<AHN_DON> lstdon = dt.AHN_DON.Where(x => x.ID == vDonID).ToList();

                    if (lstAP.Count > 0)
                    {
                        DTBIEUMAU objds = new DTBIEUMAU();
                        foreach (AHN_ANPHI oAP in lstAP)
                        {
                            string[] lstDS = oAP.DUONGSU_IDS.Split(',');
                            decimal dsID = Convert.ToDecimal(lstDS[0]);
                            AHN_DON_DUONGSU oNG = dt.AHN_DON_DUONGSU.Where(x => x.ID == dsID).FirstOrDefault();
                            string tenDS = oNG.TENDUONGSU;
                            if (lstDS.Count() > 1)
                            {
                                tenDS = "";
                                foreach (string ds in lstDS)
                                {
                                    dsID = Convert.ToDecimal(ds);
                                    AHN_DON_DUONGSU oDS = dt.AHN_DON_DUONGSU.Where(x => x.ID == dsID).FirstOrDefault();
                                    tenDS += oDS.TENDUONGSU + ", ";
                                }
                                tenDS = tenDS.Remove(tenDS.Length - 2);
                            }

                            if (oNG != null)
                            {
                                DTBIEUMAU.DTBM30DSRow r = objds.DTBM30DS.NewDTBM30DSRow();
                                r.TENVUVIEC = strTenQHPL;
                                String V_MA_THONGBAO;
                                DVCQG_THANH_TOAN_BL oBL = new DVCQG_THANH_TOAN_BL();
                                V_MA_THONGBAO = oBL.DVCQG_THANH_TOAN_SEARCH(2, vDonID, oAP.ID, "3");
                                r.MAVUVIEC = V_MA_THONGBAO;
                                if (oNG.LOAIDUONGSU == 1)
                                {

                                    if (oNG.GIOITINH == 1)
                                        strND_Gioitinh = "Ông";
                                    else
                                        strND_Gioitinh = "Bà";

                                    if (lstDS.Count() > 1)
                                        strND_Gioitinh = "Các ông/bà ";

                                    if (strND_Gioitinh == "Các ông/bà ")
                                    {
                                        AHN_DON_DUONGSU oNGHN = dt.AHN_DON_DUONGSU.Where(x => x.DONID == oAP.DONID && x.ISDAIDIEN == 1 && x.TUCACHTOTUNG_MA == "NGUYENDON").FirstOrDefault();
                                        if (oNGHN.TAMTRUID != null) strND_Diachi = getDiachi((decimal)oNGHN.TAMTRUID);
                                        if (oNGHN.TAMTRUCHITIET != null) strND_Diachi = oNGHN.TAMTRUCHITIET + ", " + strND_Diachi;
                                    }
                                    else
                                    {
                                        if (oNG.TAMTRUID != null) strND_Diachi = getDiachi((decimal)oNG.TAMTRUID);
                                        if (oNG.TAMTRUCHITIET != null) strND_Diachi = oNG.TAMTRUCHITIET + ", " + strND_Diachi;
                                    }
                                }
                                else
                                {
                                    if (oNG.NDD_DIACHIID != null) strND_Diachi = getDiachi((decimal)oNG.NDD_DIACHIID);
                                    if (oNG.NDD_DIACHICHITIET != null) strND_Diachi = oNG.NDD_DIACHICHITIET + ", " + strND_Diachi;
                                }
                                r.DIADIEM = strDiadiem;
                                r.SOTHONGBAO = oAP.SOTHONGBAO;
                                if (oAP.NGAYTHONGBAO != null)
                                {
                                    DateTime oNgayGQ = (DateTime)oAP.NGAYTHONGBAO;
                                    r.NGAYGQ = oNgayGQ.Day.ToString();
                                    r.THANGGQ = oNgayGQ.Month.ToString();
                                    r.NAMGQ = oNgayGQ.Year.ToString();
                                }

                                if (oAP.NGAYTHONGBAO != null)
                                {
                                    DateTime oNgayVietdon = (DateTime)lstdon[0].NGAYVIETDON;
                                    r.NGAYVIETDON = oNgayVietdon.Day.ToString();
                                    r.THANGVIETDON = oNgayVietdon.Month.ToString();
                                    r.NAMVIETDON = oNgayVietdon.Year.ToString();
                                }

                                r.TAMUNGANPHI = oAP.TAMUNGANPHI + "" == "" ? "0" : ((decimal)oAP.TAMUNGANPHI == 0 ? "0" : ((decimal)oAP.TAMUNGANPHI).ToString("#,#", cul));
                                r.TAMUNGBANGCHU = Cls_Comon.NumberToTextVN((decimal)oAP.TAMUNGANPHI);
                                //r.TENTOAAN = getTenToa((decimal)oDon.TOAANID);

                                DM_TOAAN oTA = dt.DM_TOAAN.Where(x => x.ID == oDon.TOAANID).FirstOrDefault();
                                DM_TOAAN_THIHANHAN_MAP oThaid = dt.DM_TOAAN_THIHANHAN_MAP.Where(x => x.TOAANID == oDon.TOAANID).FirstOrDefault();
                                decimal _oThaid = Convert.ToDecimal(oThaid.THIHANHANID);
                                DM_DONVITHIHANHAN oTHADS = dt.DM_DONVITHIHANHAN.Where(x => x.ID == _oThaid).FirstOrDefault();
                                if (oTA != null)
                                {
                                    r.TENTOAAN = getTenToa(oTA.ID);
                                    r.TENCQTHA = oTHADS.MA_TEN;
                                    r.DIACHICQTHA = oTHADS.DIACHI;
