                            nd.DIACHI = "; Địa chỉ: " + nd.DIACHI;
                            objds.DTNVLQ.AddDTNVLQRow(nd);
                            objds.AcceptChanges();
                        }
                        objds.AcceptChanges();
                        rpt77DS rpt = new rpt77DS();
                        rpt.DataSource = objds;
                        rptView.OpenReport(rpt);
                    }
                    else
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                }
                else if (vMaBC == "79-DS")
                {
                    idTitle.Text = "79-DS. Quyết định chuyển vụ án giải quyết theo thủ tục rút gọn sang giải quyết theo thủ tục thông thường";
                    //Kiểm tra xem đã có quyết định đưa vụ việc ra xét xử hay không
                    decimal IDLQD = 0, IDQD = 0;
                    DM_QD_LOAI oLQD = dt.DM_QD_LOAI.Where(x => x.MA == "DVARXX").FirstOrDefault();
                    if (oLQD != null) IDLQD = oLQD.ID;
                    DM_QD_QUYETDINH oDMQD = dt.DM_QD_QUYETDINH.Where(x => x.LOAIID == IDLQD && x.MA == "79-DS").FirstOrDefault();
                    IDQD = oDMQD.ID;
                    List<AKT_SOTHAM_QUYETDINH> lstQDXX = dt.AKT_SOTHAM_QUYETDINH.Where(x => x.DONID == vDonID && x.LOAIQDID == IDLQD && x.QUYETDINHID == IDQD).ToList();
                    if (lstThuLy.Count > 0 && lstQDXX.Count > 0)
                    {
                        AKT_SOTHAM_THULY oSTTL = lstThuLy[0];
                        AKT_SOTHAM_QUYETDINH oQD = lstQDXX[0];
                        DTBIEUMAU objds = new DTBIEUMAU();
                        DTBIEUMAU.DTBM47DSRow r = objds.DTBM47DS.NewDTBM47DSRow();
                        r.QUANHEPHAPLUAT = strTenQHPL;
                        r.DIADIEM = strDiadiem;
                        r.SOTHULY = oSTTL.SOTHULY;
                        DateTime oNgayTL = (DateTime)oSTTL.NGAYTHULY;
