                        r.DIACHI = strND_Diachi;

                        r.SOQD = oQD.SOQD;
                        DateTime oNgayQD = (DateTime)oQD.NGAYQD;
                        r.NGAYQD = oNgayQD.Day.ToString();
                        r.THANGQD = oNgayQD.Month.ToString();
                        r.NAMQD = oNgayQD.Year.ToString();
                        //Hội đồng xét xử
                        List<AKT_SOTHAM_HDXX> lstHD = dt.AKT_SOTHAM_HDXX.Where(x => x.DONID == vDonID && x.MAVAITRO == ENUM_NGUOITIENHANHTOTUNG.THAMPHAN).ToList();
                        //Thẩm phán chủ tọa

                        if (lstHD.Count > 0)
                        {
                            decimal IDCB = (decimal)lstHD[0].CANBOID;
                            DM_CANBO oCanbo = dt.DM_CANBO.Where(x => x.ID == IDCB).FirstOrDefault();
                            if (oCanbo.GIOITINH == 1)
                                r.THAMPHANCHUTOA = "Ông " + oCanbo.HOTEN;
                            else
                                r.THAMPHANCHUTOA = "Bà " + oCanbo.HOTEN;
                        }

                        objds.DTBM47DS.AddDTBM47DSRow(r);
                        //Nguyên đơn
                        foreach (AKT_DON_DUONGSU ods in lstND)
                        {
                            DTBIEUMAU.DTNGUYENDONRow nd = objds.DTNGUYENDON.NewDTNGUYENDONRow();
                            nd.DONID = oDon.ID.ToString();
                            nd.DUONGSUID = ods.ID.ToString();
                            nd.TENDUONGSU = ods.TENDUONGSU;
                            if (ods.LOAIDUONGSU == 1)
                            {
                                if (ods.GIOITINH == 1)
                                    nd.TENGIOITINH = "Ông";
                                else nd.TENGIOITINH = "Bà";
                            }
                            nd.DIENTHOAI = ods.DIENTHOAI;
                            nd.EMAIL = ods.EMAIL;
                            if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                            nd.DIACHI = ods.TAMTRUCHITIET + " " + nd.DIACHI;
                            objds.DTNGUYENDON.AddDTNGUYENDONRow(nd);
                            objds.AcceptChanges();
                        }
                        //Bị đơn
                        foreach (AKT_DON_DUONGSU ods in lstBD)
                        {
                            DTBIEUMAU.DTBIDONRow nd = objds.DTBIDON.NewDTBIDONRow();
                            nd.DONID = oDon.ID.ToString();
                            nd.DUONGSUID = ods.ID.ToString();
                            nd.TENDUONGSU = ods.TENDUONGSU;
                            if (ods.LOAIDUONGSU == 1)
                            {
                                if (ods.GIOITINH == 1)
                                    nd.TENGIOITINH = "Ông";
                                else nd.TENGIOITINH = "Bà";
                            }
                            nd.DIENTHOAI = ods.DIENTHOAI;
                            nd.EMAIL = ods.EMAIL;
                            if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                            nd.DIACHI = ods.TAMTRUCHITIET + " " + nd.DIACHI;
                            objds.DTBIDON.AddDTBIDONRow(nd);
                            objds.AcceptChanges();
                        }
                        //NVLQ
                        foreach (AKT_DON_DUONGSU ods in lstNVLQ)
                        {
                            DTBIEUMAU.DTNVLQRow nd = objds.DTNVLQ.NewDTNVLQRow();
                            nd.DONID = oDon.ID.ToString();
                            nd.DUONGSUID = ods.ID.ToString();
                            nd.TENDUONGSU = ods.TENDUONGSU;
                            if (ods.LOAIDUONGSU == 1)
                            {
                                if (ods.GIOITINH == 1)
                                    nd.TENGIOITINH = "Ông";
                                else nd.TENGIOITINH = "Bà";
                            }
                            nd.DIENTHOAI = ods.DIENTHOAI;
                            nd.EMAIL = ods.EMAIL;
                            if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                            nd.DIACHI = ods.TAMTRUCHITIET + " " + nd.DIACHI;
                            nd.DIACHI = "; Địa chỉ: " + nd.DIACHI;
                            objds.DTNVLQ.AddDTNVLQRow(nd);
                            objds.AcceptChanges();
                        }
                        objds.AcceptChanges();
                        rpt79DS rpt = new rpt79DS();
                        rpt.DataSource = objds;
                        rptView.OpenReport(rpt);
                    }
                    else
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                }
            }
            catch (Exception ex) { ltlmsg.InnerText = ex.Message; }
        }
        private void LoadReportALD_ST(decimal vDonID, ALD_DON oDon)
        {
            try
            {
                rptView.Visible = true;
                string strDiadiem = getDiaDiem((decimal)oDon.TOAANID);
                string strTenToaAn= getTenToa((decimal)oDon.TOAANID);
                decimal DonViID = Convert.ToDecimal(Session[ENUM_SESSION.SESSION_DONVIID]);
                string vMaBC = "";
                if (Request["BM"] != null)
                    vMaBC = Request["BM"] + "";
                List<ALD_SOTHAM_THULY> lstThuLy = dt.ALD_SOTHAM_THULY.Where(x => x.DONID == vDonID).OrderByDescending(x => x.NGAYTHULY).ToList();
                List<ALD_DON_THAMPHAN> lstGQD = dt.ALD_DON_THAMPHAN.Where(x => x.DONID == vDonID && x.MAVAITRO == ENUM_VAITROTHAMPHAN.VTTP_GIAIQUYETDON).OrderByDescending(x => x.NGAYPHANCONG).ToList();

                List<ALD_DON_DUONGSU> lstND = dt.ALD_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.NGUYENDON).OrderByDescending(x => x.ISDAIDIEN).ToList();
                List<ALD_DON_DUONGSU> lstBD = dt.ALD_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.BIDON).ToList();
                List<ALD_DON_DUONGSU> lstNVLQ = dt.ALD_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.QUYENNVLQ).ToList();

                List<ALD_DON_DUONGSU> lstNDDD = dt.ALD_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.NGUYENDON && x.ISDAIDIEN == 1).ToList();
                //Nguyên đơn đại diện
                string strND_Hoten = "", strND_Diachi = "", strND_Gioitinh = "", strND_Dienthoai = "", strND_Fax = "",
                    strND_Email = "", strND_NoiLamViec = "", strLoaihinhdon = "";
                if (oDon.HINHTHUCNHANDON == 1)
                    strLoaihinhdon = "nộp trực tiếp";
                else if (oDon.HINHTHUCNHANDON == 2)
                    strLoaihinhdon = "do tổ chức dịch vụ bưu chính chuyển đến ";
                if (oDon.HINHTHUCNHANDON == 3)
                    strLoaihinhdon = "nộp trực tuyến";
                string strTenQHPL = "";
                //DM_DATAITEM oTQHPL = dt.DM_DATAITEM.Where(x => x.ID == oDon.QUANHEPHAPLUATID).FirstOrDefault();
                //strTenQHPL = oTQHPL.TEN;
                strTenQHPL = getQuanhephapluat_name("ALD", "DON", "", Convert.ToDecimal(oDon.ID));

                if (lstNDDD.Count > 0)
                {
                    ALD_DON_DUONGSU oNDDD = lstNDDD[0];

                    strND_Hoten = oNDDD.LOAIDUONGSU == 1 ? Cls_Comon.FormatTenRieng(oNDDD.TENDUONGSU) : Cls_Comon.FormatTenTochuc(oNDDD.TENDUONGSU);

                    if (oNDDD.LOAIDUONGSU == 1)
                    {
                        if (oNDDD.GIOITINH == 1)
                            strND_Gioitinh = "Ông";
                        else strND_Gioitinh = "Bà";
                        if (oNDDD.TAMTRUID != null) strND_Diachi = getDiachi((decimal)oNDDD.TAMTRUID);
                        strND_Diachi = oNDDD.TAMTRUCHITIET + " " + strND_Diachi;

                    }
                    else
                    {
                        if (oNDDD.NDD_DIACHIID != null) strND_Diachi = getDiachi((decimal)oNDDD.NDD_DIACHIID);
                        strND_Diachi = oNDDD.NDD_DIACHICHITIET + " " + strND_Diachi;
                    }
                    strND_Dienthoai = oNDDD.DIENTHOAI;
                    strND_Fax = oNDDD.FAX;
                    strND_Email = oNDDD.EMAIL;
                    strND_NoiLamViec = oNDDD.DIACHICOQUAN;
                }

                if (vMaBC == "01-DS")
                {
                    idTitle.Text = "01-DS. Biên bản giao nhận tài liệu, chứng cứ";
                    DTBIEUMAU objds = new DTBIEUMAU();

                    List<ALD_DON_TAILIEU> lstTL = dt.ALD_DON_TAILIEU.Where(x => x.DONID == vDonID).ToList();
                    if (lstTL.Count == 0)
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                    foreach (ALD_DON_TAILIEU t in lstTL.GroupBy(x => new { x.NGUOIBANGIAO, x.NGAYBANGIAO, x.NGUOINHANID }).Select(x => x.FirstOrDefault()))
                    {
                        if (t.NGAYBANGIAO != null && t.NGUOIBANGIAO != null && t.NGUOINHANID != null)
                        {
                            DTBIEUMAU.DTBANGIAOTLCCRow r = objds.DTBANGIAOTLCC.NewDTBANGIAOTLCCRow();
                            r.ID = Guid.NewGuid().ToString();
                            r.QUANHEPHAPLUAT = strTenQHPL;
                            DateTime dN = (DateTime)t.NGAYBANGIAO;
                            r.NGAYBANGIAO = dN.ToString("dd/MM/yyyy");
                            r.NGAY = dN.Day.ToString();
                            r.THANG = dN.Month.ToString();
                            r.NAM = dN.Year.ToString();
                            r.NGUOINHAN = getCanBo((decimal)t.NGUOINHANID);
                            if (t.LOAIDOITUONG == 1)
                            {
                                r.TUCACHTOTUNG = "Người tham gia tố tụng";
                                ALD_DON_THAMGIATOTUNG oTT = dt.ALD_DON_THAMGIATOTUNG.Where(x => x.ID == t.NGUOIBANGIAO).FirstOrDefault();
                                r.NGUOIBANGIAO = oTT.HOTEN;
                            }
                            else
                            {
                                r.TUCACHTOTUNG = "Đương sự";
                                ALD_DON_DUONGSU oDS = dt.ALD_DON_DUONGSU.Where(x => x.ID == t.NGUOIBANGIAO).FirstOrDefault();
                                r.NGUOIBANGIAO = oDS.TENDUONGSU;
                            }
                            objds.DTBANGIAOTLCC.AddDTBANGIAOTLCCRow(r);
                            foreach (ALD_DON_TAILIEU tl in lstTL.Where(x => x.NGUOIBANGIAO == t.NGUOIBANGIAO && x.NGAYBANGIAO == t.NGAYBANGIAO && x.NGUOINHANID == t.NGUOINHANID).ToList())
                            {
                                DTBIEUMAU.DTBANGIAODSRow rt = objds.DTBANGIAODS.NewDTBANGIAODSRow();
                                rt.ID = Guid.NewGuid().ToString();
                                rt.BGID = r.ID;
                                rt.TENTAILIEU = tl.TENTAILIEU;
                                objds.DTBANGIAODS.AddDTBANGIAODSRow(rt);
                            }
                        }
                    }
                    objds.AcceptChanges();
                    rpt01DS rpt = new rpt01DS();
                    rpt.DataSource = objds;
                    rptView.OpenReport(rpt);

                }
                else if (vMaBC == "05-VDS")
                {
                    idTitle.Text = "05-VDS. Thông báo nộp tiền tạm ứng lệ phí yêu cầu giải quyết việc dân sự";
                    List<ALD_DON_XULY> lstTL = dt.ALD_DON_XULY.Where(x => x.DONID == vDonID && x.LOAIGIAIQUYET == 5).OrderByDescending(x => x.NGAYGQ_YC).ToList();
                    List<ALD_ANPHI> lstAP = dt.ALD_ANPHI.Where(x => x.DONID == vDonID && x.TINHTRANG == 0).ToList();
                    List<ALD_DON> lstdon = dt.ALD_DON.Where(x => x.ID == vDonID).ToList();

                    if (lstAP.Count > 0)
                    {
                        DTBIEUMAU objds = new DTBIEUMAU();
                        foreach (ALD_ANPHI oAP in lstAP)
                        {
                            ALD_DON_DUONGSU oNG = dt.ALD_DON_DUONGSU.Where(x => x.ID == oAP.DUONGSU_ID).FirstOrDefault();
                            if (oNG != null)
                            {
                                DTBIEUMAU.DTBM30DSRow r = objds.DTBM30DS.NewDTBM30DSRow();
                                r.TENVUVIEC = strTenQHPL;
                                String V_MA_THONGBAO;
                                DVCQG_THANH_TOAN_BL oBL = new DVCQG_THANH_TOAN_BL();
                                V_MA_THONGBAO = oBL.DVCQG_THANH_TOAN_SEARCH(2, vDonID, oAP.ID, "5");
                                r.MAVUVIEC = V_MA_THONGBAO;
                                if (oNG.LOAIDUONGSU == 1)
                                {
                                    if (oNG.GIOITINH == 1)
                                        strND_Gioitinh = "Ông";
                                    else strND_Gioitinh = "Bà";
                                    if (oNG.TAMTRUID != null) strND_Diachi = getDiachi((decimal)oNG.TAMTRUID);
                                    if (oNG.TAMTRUCHITIET != null) strND_Diachi = oNG.TAMTRUCHITIET + ", " + strND_Diachi;
                                }
                                else
                                {
                                    if (oNG.NDD_DIACHIID != null) strND_Diachi = getDiachi((decimal)oNG.NDD_DIACHIID);
                                    if (oNG.NDD_DIACHICHITIET != null) strND_Diachi = oNG.NDD_DIACHICHITIET + ", " + strND_Diachi;
                                }
                                r.DIADIEM = strDiadiem;
                                r.SOTHONGBAO = oAP.SOTHONGBAO;
                                if (oAP.NGAYTHONGBAO != null)
                                {
                                    DateTime oNgayGQ = (DateTime)oAP.NGAYTHONGBAO;
                                    r.NGAYGQ = oNgayGQ.Day.ToString();
                                    r.THANGGQ = oNgayGQ.Month.ToString();
                                    r.NAMGQ = oNgayGQ.Year.ToString();
                                }

                                if (oAP.NGAYTHONGBAO != null)
                                {
                                    DateTime oNgayVietdon = (DateTime)lstdon[0].NGAYVIETDON;
                                    r.NGAYVIETDON = oNgayVietdon.Day.ToString();
                                    r.THANGVIETDON = oNgayVietdon.Month.ToString();
                                    r.NAMVIETDON = oNgayVietdon.Year.ToString();
                                }

                                r.TAMUNGANPHI = oAP.TAMUNGANPHI + "" == "" ? "0" : ((decimal)oAP.TAMUNGANPHI == 0 ? "0" : ((decimal)oAP.TAMUNGANPHI).ToString("#,#", cul));
                                r.TAMUNGBANGCHU = Cls_Comon.NumberToTextVN((decimal)oAP.TAMUNGANPHI);
                                //r.TENTOAAN = getTenToa((decimal)oDon.TOAANID);

                                DM_TOAAN oTA = dt.DM_TOAAN.Where(x => x.ID == oDon.TOAANID).FirstOrDefault();
                                DM_TOAAN_THIHANHAN_MAP oThaid = dt.DM_TOAAN_THIHANHAN_MAP.Where(x => x.TOAANID == oDon.TOAANID).FirstOrDefault();
                                decimal _oThaid = Convert.ToDecimal(oThaid.THIHANHANID);
                                DM_DONVITHIHANHAN oTHADS = dt.DM_DONVITHIHANHAN.Where(x => x.ID == _oThaid).FirstOrDefault();
                                if (oTA != null)
                                {
                                    r.TENTOAAN = getTenToa(oTA.ID);
                                    r.TENCQTHA = oTHADS.MA_TEN;
                                    r.DIACHICQTHA = oTHADS.DIACHI;
                                }

                                r.NOIDUNGDON = oDon.NOIDUNGKHOIKIEN;
                                r.TENNGUYENDON = oNG.TENDUONGSU;
                                r.TENGIOITINH = strND_Gioitinh;
                                r.DIACHI = strND_Diachi;
                                r.EMAIL = oNG.EMAIL;
                                r.FAX = oNG.FAX;
                                r.SODIENTHOAI = oNG.DIENTHOAI;
                                r.DONID = oDon.ID.ToString() + oNG.ID.ToString();
                                r.NOILAMVIEC = oNG.DIACHICOQUAN;
                                if (lstGQD.Count > 0)
                                {
                                    r.TENTHAMPHAN = getCanBo((decimal)lstGQD[0].CANBOID);
                                }
                                objds.DTBM30DS.AddDTBM30DSRow(r);
                                objds.AcceptChanges();
                            }
                        }
                        rpt05VDS rpt = new rpt05VDS();
                        rpt.DataSource = objds;
                        rptView.OpenReport(rpt);
                    }
                    else
                    {
                        ltlmsg.InnerText = "Chưa cập nhật thông tin tạm ứng lệ phí.";
                        rptView.Visible = false;
                        return;
                    }
                }
                else if (vMaBC == "24-DS")
                {
                    idTitle.Text = "24-DS. Giấy xác nhận đã nhận đơn khởi kiện";
                    DTBIEUMAU objds = new DTBIEUMAU();
                    DTBIEUMAU.DTBM30DSRow r = objds.DTBM30DS.NewDTBM30DSRow();
                    r.TENVUVIEC = strTenQHPL;
                    r.DIADIEM = strDiadiem;
                    if (oDon.NGAYVIETDON != null)
                    {
                        DateTime oNgayViet = (DateTime)oDon.NGAYVIETDON;
                        r.NGAYVIETDON = oNgayViet.Day.ToString();
                        r.THANGVIETDON = oNgayViet.Month.ToString();
                        r.NAMVIETDON = oNgayViet.Year.ToString();
                    }
                    if (oDon.NGAYNHANDON != null)
                    {
                        DateTime oNgayViet = (DateTime)oDon.NGAYNHANDON;
                        r.NGAYNHANDON = oNgayViet.Day.ToString();
                        r.THANGNHANDON = oNgayViet.Month.ToString();
                        r.NAMNHANDON = oNgayViet.Year.ToString();
                    }
                    r.HINHTHUCDON = strLoaihinhdon;
                    r.TENTOAAN = strTenToaAn.Replace("Tòa án nhân dân\n", "TAND");
                    r.NOIDUNGDON = oDon.NOIDUNGKHOIKIEN;
                    r.TENNGUYENDON = strND_Hoten;
                    r.TENGIOITINH = strND_Gioitinh;
                    r.DIACHI = strND_Diachi;
                    r.EMAIL = strND_Email;
                    r.FAX = strND_Fax;
                    r.SODIENTHOAI = strND_Dienthoai;
                    r.DONID = oDon.ID.ToString();
