                                r.THAMPHANCHUTOA = "Bà " + oCanbo.HOTEN;
                        }
                        List<ADS_PHUCTHAM_HDXX> lstThuky = lstHD.Where(x => x.MAVAITRO == ENUM_NGUOITIENHANHTOTUNG.THUKY).ToList();
                        if (lstThuky.Count > 0)
                        {
                            decimal idTK = (decimal)lstThuky[0].CANBOID;
                            DM_CANBO oCanbo = dt.DM_CANBO.Where(x => x.ID == idTK).FirstOrDefault();
                            if (oCanbo.GIOITINH == 1)
                                r.THUKY = "Ông " + oCanbo.HOTEN;
                            else
                                r.THUKY = "Bà " + oCanbo.HOTEN;
                        }
                        objds.DTBM66DS.AddDTBM66DSRow(r);
                        objds.AcceptChanges();
                        //THẩm phán thành viên
                        objds = FillDSThamPhanThanhVien_ADS_PT(objds, lstHD);
                        //Kiểm sát viên
                        objds = FillDSKiemSatVien_ADS_PT(objds, lstHD);
                        // Nguyên đơn
                        objds = FillDSNguyenDon_ADS(oDon, objds, lstND);
                        //Bị đơn
                        objds = FillDSBiDon_ADS(oDon, objds, lstBD);
                        //NVLQ
                        objds = FillDSNguoiNVLQ_ADS(oDon, objds, lstNVLQ);
                        //Người TGTT
                        ADS_PHUCTHAM_BL oBL = new ADS_PHUCTHAM_BL();
                        DataTable tbl = oBL.ADS_PHUCTHAM_TGTT_GETLIST(vDonID);
                        objds = FillDSNguoiTGTT(objds, tbl);

                        rpt80DS rpt = new rpt80DS();
                        rpt.DataSource = objds;
                        rptView.OpenReport(rpt);
                    }
                    else
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                }
                else if (vMaBC == "81-DS")
                {
                    //Thông tin bản án/Quyết định kháng cáo, kháng nghị
                    string strKC_Nguoi = "", strKC_Toaan = "", strLOAIKCKN = "", strKN_Nguoi = "", strDIACHIKC = ""; ;
