                    List<ADS_SOTHAM_KHANGNGHI> lstkn = dt.ADS_SOTHAM_KHANGNGHI.Where(x => x.DONID == vDonID).ToList();
                    if (lstkn.Count > 0)
                    {
                        strLOAIKCKN = "kháng nghị";
