                        strKC_Toaan = getTenToa((decimal)oKN.TOAANRAQDID);
                        if (oKN.DONVIKN == 1)
                        {
                            strKN_Nguoi = "Viện trưởng";
                            if (oKN.CAPKN == 0)
                                strKN_Nguoi = strKN_Nguoi + " " + strKC_Toaan.Replace("Tòa án nhân dân", "Viện kiểm sát nhân dân");
                            else
                               if (oKN.TOAAN_VKS_KN != null) strKN_Nguoi = strKN_Nguoi + " " + getVKS((decimal)oKN.TOAAN_VKS_KN);
                        }
                        else
                        {
                            strKN_Nguoi = "Chánh án";
                            if (oKN.TOAAN_VKS_KN != null) strKN_Nguoi = strKN_Nguoi + " " + getTenToa((decimal)oKN.TOAAN_VKS_KN);
                        }
                    }
                    if (lstkc.Count > 0) //Kháng cáo
                    {
                        strLOAIKCKN = "kháng cáo";
                        ADS_SOTHAM_KHANGCAO oKN = lstkc[0];
                        if (oKN.DUONGSUID != null)
                        {
                            List<ADS_DON_DUONGSU> lstDSKC = dt.ADS_DON_DUONGSU.Where(x => x.ID == oKN.DUONGSUID).ToList();
                            if (lstDSKC.Count > 0)
                            {
                                strKC_Nguoi = lstDSKC[0].TENDUONGSU;
                                if (lstDSKC[0].LOAIDUONGSU == 1)
                                {
                                    if (lstDSKC[0].GIOITINH == 1)
                                        strKC_Nguoi = "Ông " + strKC_Nguoi;
                                    else strKC_Nguoi = "Bà " + strKC_Nguoi;
                                }
                                string strMaTCTC = lstDSKC[0].TUCACHTOTUNG_MA;
                                if (strMaTCTC == ENUM_DANSU_TUCACHTOTUNG.NGUYENDON)
                                    strKC_Nguoi += ", là nguyên đơn";
                                else if (strMaTCTC == ENUM_DANSU_TUCACHTOTUNG.BIDON)
                                    strKC_Nguoi += ", là bị đơn";
                                else if (strMaTCTC == ENUM_DANSU_TUCACHTOTUNG.QUYENNVLQ)
                                    strKC_Nguoi += ", là người có quyền lợi, nghĩa vụ liên quan";
                                strDIACHIKC = "";
                                if (lstDSKC[0].TAMTRUID != null) strDIACHIKC = getDiachi((decimal)lstDSKC[0].TAMTRUID);
                                strDIACHIKC = lstDSKC[0].TAMTRUCHITIET + " " + strDIACHIKC;
                            }
                        }
                    }
                    idTitle.Text = "81-DS. Quyết định chuyển vụ án giải quyết theo thủ tục rút gọn sang giải quyết theo thủ tục thông thường (tại Tòa án cấp phúc thẩm)";
                    decimal IDLQD = 0, IDQD = 0;
                    DM_QD_LOAI oLQD = dt.DM_QD_LOAI.Where(x => x.MA == "DVARXX").FirstOrDefault();
                    if (oLQD != null) IDLQD = oLQD.ID;
                    DM_QD_QUYETDINH oDMQD = dt.DM_QD_QUYETDINH.Where(x => x.LOAIID == IDLQD && x.MA == "81-DS").FirstOrDefault();
                    IDQD = oDMQD.ID;
                    List<ADS_PHUCTHAM_QUYETDINH> lstQDXX = dt.ADS_PHUCTHAM_QUYETDINH.Where(x => x.DONID == vDonID && x.LOAIQDID == IDLQD && x.QUYETDINHID == IDQD).ToList();

                    if (lstThuLy.Count > 0 && lstQDXX.Count > 0)
                    {
                        ADS_PHUCTHAM_THULY oSTTL = lstThuLy[0];
                        ADS_PHUCTHAM_QUYETDINH oQD = lstQDXX[0];
                        //DM_DATAITEM oTQHPL = dt.DM_DATAITEM.Where(x => x.ID == oSTTL.QUANHEPHAPLUATID).FirstOrDefault();
                        //strTenQHPL = oTQHPL.TEN;
                        strTenQHPL = getQuanhephapluat_name("ADS", "PHUCTHAM", "THULY", Convert.ToDecimal(oSTTL.DONID));

                        DTBIEUMAU objds = new DTBIEUMAU();
                        DTBIEUMAU.DTBM66DSRow r = objds.DTBM66DS.NewDTBM66DSRow();
                        r.QUANHEPHAPLUAT = strTenQHPL;
                        r.DIADIEM = strDiadiem;
                        r.LOAIKCKN = strLOAIKCKN;
                        r.SOTHULY = oSTTL.SOTHULY;
                        DateTime oNgayTL = (DateTime)oSTTL.NGAYTHULY;
                        r.NGAYTHULY = oNgayTL.Day.ToString();
                        r.THANGTHULY = oNgayTL.Month.ToString();
                        r.NAMTHULY = oNgayTL.Year.ToString();
                        r.TENTOAAN = getTenToa((decimal)oSTTL.TOAANID);
                        r.NGUOIKCKN = strKC_Nguoi;
                        r.DIACHIKC = strDIACHIKC;
                        r.VKSKHANGNGHI = strKN_Nguoi;
                        r.SOQD = oQD.SOQD;
                        DateTime oNgayQD = (DateTime)oQD.NGAYQD;
                        r.NGAYQD = oNgayQD.Day.ToString();
                        r.THANGQD = oNgayQD.Month.ToString();
                        r.NAMQD = oNgayQD.Year.ToString();
                        r.LOAIAN = "DS";
                        //Hội đồng xét xử                       
                        List<ADS_PHUCTHAM_HDXX> lstHD = dt.ADS_PHUCTHAM_HDXX.Where(x => x.DONID == vDonID && x.MAVAITRO == ENUM_NGUOITIENHANHTOTUNG.THAMPHAN).ToList();
                        if (lstHD.Count > 0)
                        {
                            decimal IDTP = (decimal)lstHD[0].CANBOID;
                            DM_CANBO oCanbo = dt.DM_CANBO.Where(x => x.ID == IDTP).FirstOrDefault();
                            if (oCanbo.GIOITINH == 1)
                                r.THAMPHANCHUTOA = "Ông " + oCanbo.HOTEN;
                            else
                                r.THAMPHANCHUTOA = "Bà " + oCanbo.HOTEN;
                        }
                        objds.DTBM66DS.AddDTBM66DSRow(r);
                        objds.AcceptChanges();
                        //Nguyên đơn
                        objds = FillDSNguyenDon_ADS(oDon, objds, lstND);
                        //Bị đơn
                        objds = FillDSBiDon_ADS(oDon, objds, lstBD);
                        //NVLQ
                        objds = FillDSNguoiNVLQ_ADS(oDon, objds, lstNVLQ);

                        rpt81DS rpt = new rpt81DS();
                        rpt.DataSource = objds;
                        rptView.OpenReport(rpt);
                    }
                    else
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                }
            }
            catch (Exception ex) { ltlmsg.InnerText = ex.Message; }
        }
        private void LoadReportAHN_PT(decimal vDonID, AHN_DON oDon)
        {
            try
