                    DM_QD_QUYETDINH oDMQD = dt.DM_QD_QUYETDINH.Where(x => x.LOAIID == IDLQD && x.MA == "81-DS").FirstOrDefault();
                    IDQD = oDMQD.ID;
                    List<AKT_PHUCTHAM_QUYETDINH> lstQDXX = dt.AKT_PHUCTHAM_QUYETDINH.Where(x => x.DONID == vDonID && x.LOAIQDID == IDLQD && x.QUYETDINHID == IDQD).ToList();

                    if (lstThuLy.Count > 0 && lstQDXX.Count > 0)
                    {
                        AKT_PHUCTHAM_THULY oSTTL = lstThuLy[0];
                        AKT_PHUCTHAM_QUYETDINH oQD = lstQDXX[0];
                        //DM_DATAITEM oTQHPL = dt.DM_DATAITEM.Where(x => x.ID == oSTTL.QUANHEPHAPLUATID).FirstOrDefault();
                        //strTenQHPL = oTQHPL.TEN;
                        strTenQHPL = getQuanhephapluat_name("AKT", "PHUCTHAM", "THULY", Convert.ToDecimal(oSTTL.DONID));
                        DTBIEUMAU objds = new DTBIEUMAU();
                        DTBIEUMAU.DTBM66DSRow r = objds.DTBM66DS.NewDTBM66DSRow();
                        r.QUANHEPHAPLUAT = strTenQHPL;
                        r.DIADIEM = strDiadiem;
                        r.LOAIKCKN = strLOAIKCKN;
                        r.SOTHULY = oSTTL.SOTHULY;
                        DateTime oNgayTL = (DateTime)oSTTL.NGAYTHULY;
                        r.NGAYTHULY = oNgayTL.Day.ToString();
                        r.THANGTHULY = oNgayTL.Month.ToString();
                        r.NAMTHULY = oNgayTL.Year.ToString();
                        r.TENTOAAN = getTenToa((decimal)oSTTL.TOAANID);
                        r.NGUOIKCKN = strKC_Nguoi;
                        r.DIACHIKC = strDIACHIKC;
                        r.VKSKHANGNGHI = strKN_Nguoi;
                        r.SOQD = oQD.SOQD;
                        DateTime oNgayQD = (DateTime)oQD.NGAYQD;
                        r.NGAYQD = oNgayQD.Day.ToString();
                        r.THANGQD = oNgayQD.Month.ToString();
                        r.NAMQD = oNgayQD.Year.ToString();
                        r.LOAIAN = "KDTM";
                        //Hội đồng xét xử                       
                        List<AKT_PHUCTHAM_HDXX> lstHD = dt.AKT_PHUCTHAM_HDXX.Where(x => x.DONID == vDonID && x.MAVAITRO == ENUM_NGUOITIENHANHTOTUNG.THAMPHAN).ToList();
                        if (lstHD.Count > 0)
                        {
                            decimal IDTP = (decimal)lstHD[0].CANBOID;
                            DM_CANBO oCanbo = dt.DM_CANBO.Where(x => x.ID == IDTP).FirstOrDefault();
                            if (oCanbo.GIOITINH == 1)
                                r.THAMPHANCHUTOA = "Ông " + oCanbo.HOTEN;
                            else
                                r.THAMPHANCHUTOA = "Bà " + oCanbo.HOTEN;
                        }
                        objds.DTBM66DS.AddDTBM66DSRow(r);
                        //Nguyên đơn
                        foreach (AKT_DON_DUONGSU ods in lstND)
                        {
                            DTBIEUMAU.DTNGUYENDONRow nd = objds.DTNGUYENDON.NewDTNGUYENDONRow();
                            nd.DONID = oDon.ID.ToString();
                            nd.DUONGSUID = ods.ID.ToString();
                            nd.TENDUONGSU = ods.TENDUONGSU;
                            if (ods.LOAIDUONGSU == 1)
                            {
                                if (ods.GIOITINH == 1)
                                    nd.TENGIOITINH = "Ông";
                                else nd.TENGIOITINH = "Bà";
                            }
                            nd.DIENTHOAI = ods.DIENTHOAI;
                            nd.EMAIL = ods.EMAIL;
                            if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                            nd.DIACHI = ods.TAMTRUCHITIET + " " + nd.DIACHI;
                            objds.DTNGUYENDON.AddDTNGUYENDONRow(nd);
                            objds.AcceptChanges();
                        }
                        //Bị đơn
                        foreach (AKT_DON_DUONGSU ods in lstBD)
                        {
                            DTBIEUMAU.DTBIDONRow nd = objds.DTBIDON.NewDTBIDONRow();
                            nd.DONID = oDon.ID.ToString();
                            nd.DUONGSUID = ods.ID.ToString();
                            nd.TENDUONGSU = ods.TENDUONGSU;
                            if (ods.LOAIDUONGSU == 1)
                            {
                                if (ods.GIOITINH == 1)
                                    nd.TENGIOITINH = "Ông";
                                else nd.TENGIOITINH = "Bà";
                            }
                            nd.DIENTHOAI = ods.DIENTHOAI;
                            nd.EMAIL = ods.EMAIL;
                            if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                            nd.DIACHI = ods.TAMTRUCHITIET + " " + nd.DIACHI;
                            objds.DTBIDON.AddDTBIDONRow(nd);
                            objds.AcceptChanges();
                        }
                        //NVLQ
                        foreach (AKT_DON_DUONGSU ods in lstNVLQ)
                        {
                            DTBIEUMAU.DTNVLQRow nd = objds.DTNVLQ.NewDTNVLQRow();
                            nd.DONID = oDon.ID.ToString();
                            nd.DUONGSUID = ods.ID.ToString();
                            nd.TENDUONGSU = ods.TENDUONGSU;
                            if (ods.LOAIDUONGSU == 1)
                            {
                                if (ods.GIOITINH == 1)
                                    nd.TENGIOITINH = "Ông";
                                else nd.TENGIOITINH = "Bà";
                            }
                            nd.DIENTHOAI = ods.DIENTHOAI;
                            nd.EMAIL = ods.EMAIL;
                            if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                            nd.DIACHI = ods.TAMTRUCHITIET + " " + nd.DIACHI;
                            nd.DIACHI = "; Địa chỉ: " + nd.DIACHI;
                            objds.DTNVLQ.AddDTNVLQRow(nd);
                            objds.AcceptChanges();
                        }

                        objds.AcceptChanges();
                        rpt81DS rpt = new rpt81DS();
                        rpt.DataSource = objds;
                        rptView.OpenReport(rpt);
                    }
                    else
                    {
                        ltlmsg.InnerText = "Không tìm thấy dữ liệu của báo cáo " + vMaBC + ".";
                        return;
                    }
                }
            }
            catch (Exception ex) { ltlmsg.InnerText = ex.Message; }
        }
        private void LoadReportALD_PT(decimal vDonID, ALD_DON oDon)
        {
            try
            {
                string strDiadiem = getDiaDiem((decimal)oDon.TOAPHUCTHAMID);
                string strTenToaAn= getTenToa((decimal)oDon.TOAANID);
                decimal DonViID = Convert.ToDecimal(Session[ENUM_SESSION.SESSION_DONVIID]);
                string vMaBC = "";
                if (Request["BM"] != null)
                    vMaBC = Request["BM"] + "";
                List<ALD_PHUCTHAM_THULY> lstThuLy = dt.ALD_PHUCTHAM_THULY.Where(x => x.DONID == vDonID).OrderByDescending(x => x.NGAYTHULY).ToList();
                List<ALD_DON_THAMPHAN> lstGQD = dt.ALD_DON_THAMPHAN.Where(x => x.DONID == vDonID && x.MAVAITRO == ENUM_VAITROTHAMPHAN.VTTP_GIAIQUYETPHUCTHAM).OrderByDescending(x => x.NGAYPHANCONG).ToList();
                List<ALD_DON_DUONGSU> lstND = dt.ALD_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.NGUYENDON).OrderByDescending(x => x.ISDAIDIEN).ToList();
                List<ALD_DON_DUONGSU> lstBD = dt.ALD_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.BIDON).ToList();
                List<ALD_DON_DUONGSU> lstNVLQ = dt.ALD_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.QUYENNVLQ).ToList();
                List<ALD_DON_DUONGSU> lstNDDD = dt.ALD_DON_DUONGSU.Where(x => x.DONID == vDonID && x.TUCACHTOTUNG_MA == ENUM_DANSU_TUCACHTOTUNG.NGUYENDON && x.ISDAIDIEN == 1).ToList();

