                    decimal IDLQD = 0, IDQD = 0;
                    DM_QD_LOAI oLQD = dt.DM_QD_LOAI.Where(x => x.MA == "DVARXX").FirstOrDefault();
                    if (oLQD != null) IDLQD = oLQD.ID;
                    DM_QD_QUYETDINH oDMQD = dt.DM_QD_QUYETDINH.Where(x => x.LOAIID == IDLQD && x.MA == "81-DS").FirstOrDefault();
                    IDQD = oDMQD.ID;
                    List<ALD_PHUCTHAM_QUYETDINH> lstQDXX = dt.ALD_PHUCTHAM_QUYETDINH.Where(x => x.DONID == vDonID && x.LOAIQDID == IDLQD && x.QUYETDINHID == IDQD).ToList();

                    if (lstThuLy.Count > 0 && lstQDXX.Count > 0)
                    {
