                            {
                                if (ods.GIOITINH == 1)
                                    nd.TENGIOITINH = "Ông";
                                else nd.TENGIOITINH = "Bà";
                            }
                            nd.DIENTHOAI = ods.DIENTHOAI;
                            nd.EMAIL = ods.EMAIL;
                            if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                            nd.DIACHI = ods.TAMTRUCHITIET + " " + nd.DIACHI;
