        private DTBIEUMAU FillDSNguyenDon_ADS(ADS_DON oDon, DTBIEUMAU objds, List<ADS_DON_DUONGSU> lstND)
        {
            DTBIEUMAU.DTNGUYENDONRow nd;
            foreach (ADS_DON_DUONGSU ods in lstND)
            {
                nd = objds.DTNGUYENDON.NewDTNGUYENDONRow();
                nd.DONID = oDon.ID.ToString();
                nd.DUONGSUID = ods.ID.ToString();
                nd.TENDUONGSU = ods.TENDUONGSU;
                nd.NAMSINH = ods.NAMSINH?.ToString();
                if (ods.LOAIDUONGSU == 1)
                {
                    if (ods.GIOITINH == 1)
                        nd.TENGIOITINH = "Ông";
                    else nd.TENGIOITINH = "Bà";
                }
                nd.DIENTHOAI = ods.DIENTHOAI;
                nd.EMAIL = ods.EMAIL;
                nd.NOILAMVIEC = ods.DIACHICOQUAN;
                if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                nd.DIACHI = ods.TAMTRUCHITIET + " " + nd.DIACHI;
                objds.DTNGUYENDON.AddDTNGUYENDONRow(nd);
            }
            objds.AcceptChanges();
            return objds;
        }
        private DTBIEUMAU FillDSNguyenDon_ADS1(ADS_DON oDon, DTBIEUMAU objds, List<ADS_DON_DUONGSU> lstND)
        {
            DTBIEUMAU.DTNGUYENDONRow nd;
            lstND = lstND.Where(x => x.ISDAIDIEN == 1).ToList();
            foreach (ADS_DON_DUONGSU ods in lstND)
            {
                nd = objds.DTNGUYENDON.NewDTNGUYENDONRow();
                nd.DONID = oDon.ID.ToString();
                nd.DUONGSUID = ods.ID.ToString();
                nd.TENDUONGSU = ods.TENDUONGSU;
                nd.NAMSINH = string.IsNullOrEmpty(ods.NAMSINH?.ToString()) || ods.NAMSINH == 0
              ? string.Empty : $", sinh năm {ods.NAMSINH}.";
                if (ods.LOAIDUONGSU == 1)
                {
                    if (ods.GIOITINH == 1)
                        nd.TENGIOITINH = "Ông";
                    else nd.TENGIOITINH = "Bà";
                }
                nd.DIENTHOAI = ods.DIENTHOAI;
                nd.EMAIL = ods.EMAIL;
                nd.NOILAMVIEC = ods.DIACHICOQUAN;
                if (ods.TAMTRUID != null) nd.DIACHI = getDiachi((decimal)ods.TAMTRUID);
                nd.DIACHI = !string.IsNullOrEmpty(ods.TAMTRUCHITIET) || !string.IsNullOrEmpty(nd.DIACHI)
    ? "Nơi ở: " + (ods.TAMTRUCHITIET + " " + nd.DIACHI + ".").Trim()
    : null;
                objds.DTNGUYENDON.AddDTNGUYENDONRow(nd);
            }
            objds.AcceptChanges();
            return objds;
        }
