        private DTBIEUMAU FillDSNguoiTGTT(DTBIEUMAU objds, DataTable tbl)
        {
            if (tbl != null && tbl.Rows.Count > 0)
            {
                DTBIEUMAU.DTNGUOITGTTRow nd;
                foreach (DataRow dr in tbl.Rows)
                {
                    nd = objds.DTNGUOITGTT.NewDTNGUOITGTTRow();
                    nd.TENNGUOITGTT = dr["HOTEN"] + "";
                    nd.DIACHI = "; Địa chỉ: " + dr["TAMTRU"] + "";
                    objds.DTNGUOITGTT.AddDTNGUOITGTTRow(nd);
                }
                objds.AcceptChanges();
            }
            return objds;
        }

        protected void ExportData(string fileName, string path)
        {
            try
            {
                //copy to MemoryStream
                MemoryStream ms = new MemoryStream();
                using (FileStream fs = File.OpenRead(Path.Combine(path)))
                {
                    fs.CopyTo(ms);
                }

                //Delete file
                if (File.Exists(Path.Combine(path)))
                    File.Delete(Path.Combine(path));

                //Download file
                Response.Clear();
                Response.ContentType = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
                Response.AddHeader("Content-Disposition", "attachment;filename=" + fileName);
                Response.BinaryWrite(ms.ToArray());
                Response.Flush();
            }
            catch { }

            Response.End();
        }
    }
}